UPDATE schedule s
JOIN alba a ON a.alba_id = s.alba_id
SET s.schedule_time = #{req.scheduleTime}
WHERE s.schedule_id = #{req.scheduleId}
  AND a.store_id = #{storeId}
  AND a.is_active = b'1'

mapper.insert:
INSERT INTO work (alba_id, work_date, work_in, work_status)
SELECT #{albaId}, #{workDate}, #{workIn}, #{workStatus}
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1
    FROM work
    WHERE alba_id = #{albaId}
      AND DATE(work_in) = #{workDate}
      AND work_out IS NULL
)

mapper.update:
UPDATE work
SET work_out = #{workOut}
WHERE alba_id = #{albaId}
  AND DATE(work_in) = #{workDate}
  AND work_out IS NULL
